 using Contoso.Text;

 namespace Contoso.Text.Tests;

 [TestClass]
 public sealed class StringFormatterTests
 {
     private readonly StringFormatter _formatter = new();

     // --- FormatPhoneNumber ---

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCode()
     {
         var result = _formatter.FormatPhoneNumber("2125551234");

         Assert.StartsWith("(212)", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_EndsWithLastFour()
     {
         var result = _formatter.FormatPhoneNumber("2125551234");

         Assert.EndsWith("1234", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ReturnsExpectedFormat()
     {
         var result = _formatter.FormatPhoneNumber("2125551234");

         Assert.AreEqual("(212) 555-1234", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));
     }

     [TestMethod]
     [DataRow("123")]
     [DataRow("12345678901")]
     public void FormatPhoneNumber_WrongLength_ThrowsArgumentException(string digits)
     {
         Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber(digits));
     }

     // --- BuildGreeting ---

     [TestMethod]
     public void BuildGreeting_DefaultTitle_StartsWithDearMr()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.StartsWith("Dear Mr.", result);
     }

     [TestMethod]
     public void BuildGreeting_DefaultTitle_EndsWithComma()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.EndsWith(",", result);
     }

     [TestMethod]
     public void BuildGreeting_CustomTitle_StartsWithDearAndTitle()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         Assert.StartsWith("Dear Dr.", result);
     }

     [TestMethod]
     public void BuildGreeting_CustomTitle_ReturnsExpectedFormat()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         Assert.AreEqual("Dear Dr. Johnson,", result);
     }

     [TestMethod]
     public void BuildGreeting_NullName_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.BuildGreeting(null!));
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
     public void BuildGreeting_EmptyOrWhitespaceName_ThrowsArgumentException(string name)
     {
         Assert.ThrowsExactly<ArgumentException>(() => _formatter.BuildGreeting(name));
     }

     // --- GenerateSlug ---

     [TestMethod]
     public void GenerateSlug_SimpleTitle_ReturnsLowercaseHyphenated()
     {
         var result = _formatter.GenerateSlug("Hello World");

         Assert.AreEqual("hello-world", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleWithSpecialChars_DoesNotStartWithHyphen()
     {
         var result = _formatter.GenerateSlug("  --My Post!  ");

         Assert.StartsWith("my", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleWithSpecialChars_DoesNotEndWithHyphen()
     {
         var result = _formatter.GenerateSlug("  --My Post!  ");

         Assert.EndsWith("post", result);
     }

     [TestMethod]
     public void GenerateSlug_MixedCase_ReturnsAllLowercase()
     {
         var result = _formatter.GenerateSlug("CamelCase Title HERE");

         Assert.AreEqual("camelcase-title-here", result);
     }

     [TestMethod]
     public void GenerateSlug_WhitespaceOnly_Throws()
     {
         Assert.ThrowsExactly<ArgumentException>(() => _formatter.GenerateSlug("   "));
     }

     // --- FormatCurrency ---

     [TestMethod]
     public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
     {
         var result = _formatter.FormatCurrency(9.99m);

         Assert.StartsWith("$", result);
     }

     [TestMethod]
     public void FormatCurrency_CustomSymbol_StartsWithSymbol()
     {
         var result = _formatter.FormatCurrency(19.99m, "€");

         Assert.StartsWith("€", result);
     }

     [TestMethod]
     public void FormatCurrency_WholeNumber_EndsWithTwoDecimalZeros()
     {
         var result = _formatter.FormatCurrency(100m);

         Assert.EndsWith(".00", result);
     }

     [TestMethod]
     public void FormatCurrency_WithCents_ReturnsExpectedFormat()
     {
         var result = _formatter.FormatCurrency(42.50m, "£");

         Assert.AreEqual("£42.50", result);
     }

     [TestMethod]
     public void FormatCurrency_NegativeAmount_StartsWithSymbolAndMinus()
     {
         var result = _formatter.FormatCurrency(-5.00m);

         Assert.StartsWith("$-", result);
     }
 }

